draw:
var Z = Math.round(p.Z);
var nsel = Math.round(p.n);
var NMAX = 4;
var cx = W * 0.42, cy = H * 0.5;
var Rmax = Math.min(W * 0.36, H * 0.42);
var scale = Rmax / (NMAX * NMAX);
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "left";
ctx.textBaseline = "middle";

// orbits
var i;
for (i = 1; i <= NMAX; i++) {
  var R = i * i * scale;
  ctx.beginPath();
  ctx.arc(cx, cy, R, 0, Math.PI * 2);
  if (i === nsel) {
    ctx.strokeStyle = C.accent;
    ctx.lineWidth = 2;
    ctx.setLineDash([]);
  } else {
    ctx.strokeStyle = C.faint;
    ctx.lineWidth = 1;
    ctx.setLineDash([3, 4]);
  }
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = (i === nsel) ? C.accent : C.faint;
  ctx.fillText("n=" + i, cx + 3, cy - R - 8);
}
ctx.lineWidth = 1;

// nucleus
ctx.fillStyle = C.ink;
ctx.beginPath();
ctx.arc(cx, cy, 5, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("nucleus +" + Z + "e", cx + 9, cy + 12);

// electron: period goes as n^3 / Z^2
var period = 1.1 * nsel * nsel * nsel / (Z * Z);
var ang = 2 * Math.PI * (t / period);
var Rn = nsel * nsel * scale;
var ex = cx + Rn * Math.cos(ang);
var ey = cy - Rn * Math.sin(ang);

// radius line
ctx.strokeStyle = C.rule;
ctx.setLineDash([2, 3]);
ctx.beginPath();
ctx.moveTo(cx, cy);
ctx.lineTo(ex, ey);
ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.rule;
ctx.fillText("r", (cx + ex) / 2 + 5, (cy + ey) / 2 - 5);

// velocity arrow, tangent
var vx = -Math.sin(ang), vy = -Math.cos(ang);
var alen = 26;
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.moveTo(ex, ey);
ctx.lineTo(ex + vx * alen, ey + vy * alen);
ctx.stroke();
var hx = ex + vx * alen, hy = ey + vy * alen;
ctx.beginPath();
ctx.moveTo(hx, hy);
ctx.lineTo(hx - vx * 6 - vy * 4, hy - vy * 6 + vx * 4);
ctx.lineTo(hx - vx * 6 + vy * 4, hy - vy * 6 - vx * 4);
ctx.closePath();
ctx.fillStyle = C.figure;
ctx.fill();
ctx.lineWidth = 1;
ctx.fillStyle = C.figure;
ctx.fillText("v", hx + 6, hy - 2);

ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.arc(ex, ey, 4.5, 0, Math.PI * 2);
ctx.fill();

// side panel numbers
var r_nm = 0.0529 * nsel * nsel / Z;
var v_ms = 2.19e6 * Z / nsel;
var E_eV = -13.6 * Z * Z / (nsel * nsel);
var px = W - 6;
ctx.textAlign = "right";
ctx.fillStyle = C.ink;
ctx.fillText("r = " + r_nm.toFixed(4) + " nm", px, 18);
ctx.fillStyle = C.figure;
ctx.fillText("v = " + (v_ms / 1e6).toFixed(3) + "e6 m/s", px, 36);
ctx.fillStyle = C.ink;
ctx.fillText("E = " + E_eV.toFixed(2) + " eV", px, 54);
ctx.fillStyle = C.rule;
ctx.fillText("L = " + nsel + " hbar", px, 72);
ctx.textAlign = "left";

out.note = "n = " + nsel + ", Z = " + Z + ": r = " + r_nm.toFixed(4) + " nm, v = " + v_ms.toExponential(2) + " m/s, one orbit every " + (2 * Math.PI * (0.0529e-9 * nsel * nsel / Z) / v_ms).toExponential(2) + " s";
